static void read(u32 addr, u8 *buf, u32 n)
{
    command(CMD_READ, addr);
    JL_SPI0->CON |= SPI_RX;
    while (n--)
        *buf++ = (u8)xfer(0xFFu);
    JL_SPI0->CON &= ~SPI_RX;
