{
    u32 i, n = sizeof default_routes / sizeof default_routes[0];

    s->version = MIDI_SETTINGS_VERSION;
    s->channel = MIDI_OMNI;
    s->bend_range = 2;
    s->routes = (u8)n;
    for (i = 0; i < MIDI_CC_ROUTES; i++) {
        s->cc[i].cc = i < n ? default_routes[i][0] : 0;
        s->cc[i].to = i < n ? default_routes[i][1] : MIDI_TO_NONE;
    }
    s->out_channel = 1;
    s->thru = 0;
    s->local = 1;
    s->reserved = 0;
}

