    assert len(name) <= 12 and all(32 <= c < 127 for c in name), p["name"]
    b[4:4 + len(name)] = name
    b[16] = p["algorithm"]
    b[17] = p["feedback"]
    b[18] = 1 if p["mono"] else 0
    b[19] = p["glide"]
    b[20] = p["transpose"] & 0xFF
    b[21] = p["pitch_depth"] & 0xFF
    b[22:25] = bytes(p["pitch_rates"])
    b[25:29] = bytes(v & 0xFF for v in p["pitch_levels"])
    for i, o in enumerate(p["ops"]):
        at = OP_OFFSET + OP_BYTES * i
        if o["mode"] == RATIO:
            f = int(round(o["freq"] * 256))
        else:
            f = int(round(o["freq"] * 4))
        assert 0 <= f < 65536
        b[at] = o["mode"]
        b[at + 1], b[at + 2] = f & 0xFF, f >> 8
        b[at + 3] = o["detune"] & 0xFF
        b[at + 4] = o["level"]
        b[at + 5] = o["velocity"]
        b[at + 6:at + 10] = bytes(o["rates"])
        b[at + 10:at + 13] = bytes(o["levels"])
    s = fletcher16(b[:SUM_OFFSET])
    b[SUM_OFFSET], b[SUM_OFFSET + 1] = s & 0xFF, s >> 8
    return bytes(b)


void midi_settings_default(struct midi_settings *s)
{
    u32 i, n = sizeof default_routes / sizeof default_routes[0];

    s->version = MIDI_SETTINGS_VERSION;
    s->channel = MIDI_OMNI;
    s->bend_range = 2;
    s->routes = (u8)n;
    for (i = 0; i < MIDI_CC_ROUTES; i++) {
        s->cc[i].cc = i < n ? default_routes[i][0] : 0;
        s->cc[i].to = i < n ? default_routes[i][1] : MIDI_TO_NONE;
    }
    s->out_channel = 1;
    s->thru = 0;
    s->local = 1;
    s->reserved = 0;
}

